import {TONES,AMPS,GUITARS,DEFAULT_RIG} from './data.js';
import {CONFIG} from './config.js';
import {KNOB_KEYS,EFFECT_TYPES,MAX_BACKUP_BYTES,backupParts,validateGrounding,clamp,cleanText,safeUrl,validateRig,validateBackup,validateResearch,adaptTone} from './core.js';

const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',save:'<path d="M6 4h12v17l-6-4-6 4Z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',plus:'<path d="M12 5v14M5 12h14"/>',trash:'<path d="M4 7h16M9 7V3h6v4M6 7l1 14h10l1-14M10 11v6m4-6v6"/>'})[name]||''}</svg>`;
const labels={gain:'Gain',bass:'Bass',middle:'Middle',treble:'Treble',presence:'Presence',guitarTone:'Gtr tone'};
const pickupNames={single:'Single-coil',humbucker:'Humbucker',p90:'P-90',active:'Active',mixed:'Mixed / split'};
let storageOK=true,restoreNotice='';
let stored={};try{stored=JSON.parse(localStorage.getItem('tonezero-v1')||'{}')}catch{storageOK=false;restoreNotice='Device storage is unavailable or damaged. Export a backup before closing.'}
let rig=structuredClone(DEFAULT_RIG),saved=[];
try{if(stored.rig){const data=validateBackup({format:'tonezero-backup',version:1,rig:stored.rig,saved:stored.saved||[]});rig=data.rig;saved=data.saved}}catch{restoreNotice='A saved profile could not be read. Your original storage has been left untouched until you make a change.'}
let view=['explore','rig','saved'].includes(location.hash.slice(1))?location.hash.slice(1):'explore';
let query='',filter='All tones',selected=TONES.find(t=>t.id==='little-wing'),values={},result, guitarTone=8.5;
let apiBase=validEndpoint(stored.apiBase)||CONFIG.apiBase,siteKey=cleanText(stored.siteKey,150)||CONFIG.turnstileSiteKey||'';
let motion=stored.motion!==false,toastTimer,animationId,frame=0,installPrompt=null,researchAbort=null,researchData=null,widgetId=null,researchToken='',researchKind='guitar',lastResearchQuery='';
let lastFocus=null,modalEpoch=0;
const modal=$('#modal');
function validEndpoint(v){try{const u=new URL(v);if(u.protocol!=='https:'&&!(['localhost','127.0.0.1'].includes(u.hostname)&&u.protocol==='http:'))return '';return u.origin}catch{return ''}}
function persist(){try{localStorage.setItem('tonezero-v1',JSON.stringify({rig,saved,apiBase,siteKey,motion}));storageOK=true}catch{storageOK=false;toast('Storage is full or unavailable. Export your tones to keep them.')}$('#saved-count').textContent=saved.length;$('#storage-warning').hidden=storageOK;return storageOK}
function savedFeedback(message){toast(storageOK?message:'Changes kept in memory only. Export a backup before closing.')}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function recalculate(){result=adaptTone(selected,rig);values={...result.values};guitarTone=result.guitarTone}
function changeView(next){view=next;history.replaceState(null,'','#'+view);render();window.scrollTo({top:0,behavior:'instant'})}
function render(){cancelAnimationFrame(animationId);document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('#saved-count').textContent=saved.length;$('#main').innerHTML=view==='rig'?rigView():view==='saved'?savedView():exploreView();if(view==='explore'){renderList();renderSession()}if(view==='rig'){renderCatalog();appendGrounding($('#rig-form').parentElement,gearResearch())}if(view==='saved'){document.querySelectorAll('.saved-card').forEach((card,i)=>appendGrounding(card,[{title:saved[i].tone.title,data:saved[i].tone.research}]))}$('#storage-warning').hidden=storageOK;}
function miniWave(i){return `<span class="mini-wave" aria-hidden="true">${[10,21,33,25,37,17,8].map((h,j)=>`<i style="height:${Math.max(6,h+Math.sin(i+j)*6)}px"></i>`).join('')}</span>`}
function category(t){if(t.family==='high-gain'||/fuzz|grunge/i.test(t.style))return 'Heavy';if(t.family==='lead')return 'Lead';if(t.family==='crunch'||t.family==='pushed')return 'Crunch';return 'Clean'}
function exploreView(){return `<section class="intro fade-in"><div><div class="eyebrow"><span class="line"></span>YOUR NEXT SOUND STARTS HERE</div><h1>Find your <em>frequency.</em></h1></div><p>Choose a song. Dial in your gear.<br>Make the sound your own.</p></section><div class="workspace"><section class="library fade-in delay-1" aria-label="Tone library"><label class="search-field">${icon('search')}<input id="tone-search" type="search" maxlength="160" placeholder="Search a song or artist" aria-label="Search a song or artist" value="${esc(query)}"><span class="shortcut" aria-hidden="true">/</span></label><div class="filters" role="group" aria-label="Filter tones">${['All tones','Clean','Crunch','Lead','Heavy'].map(f=>`<button class="chip ${filter===f?'active':''}" aria-pressed="${filter===f}" data-filter="${f}">${f}</button>`).join('')}</div><div class="section-label"><span>Starting points</span><span id="tone-results-count"></span></div><div class="tone-list" id="tone-list"></div><button class="research-cta" data-action="research-song"><span class="spark" aria-hidden="true">✧</span><span id="research-song-label">Find another song with AI<small>Web research with source links</small></span><span style="margin-left:auto">↗</span></button><p class="library-note">Original starting points. Fine-tune with your ears.</p><button class="text-button" data-action="custom-tone">Create a custom tone</button></section><section id="session" class="session fade-in delay-1" aria-label="Tone settings"></section></div>`}
function renderList(){const list=TONES.filter(t=>(filter==='All tones'||category(t)===filter)&&`${t.title} ${t.artist} ${t.style}`.toLowerCase().includes(query.toLowerCase()));$('#tone-results-count').textContent=String(list.length).padStart(2,'0');$('#tone-list').innerHTML=list.length?list.map((t,i)=>`<button class="tone-card ${selected.id===t.id?'selected':''}" data-tone="${t.id}" aria-pressed="${selected.id===t.id}">${miniWave(i)}<span class="card-body"><span class="title">${esc(t.title)}</span><span class="artist">${esc(t.artist)}</span></span><span class="tag">${category(t)}</span></button>`).join(''):`<div class="empty"><h3>No built-in match</h3><p>Try a different title, or research this song below.</p></div>`;$('#research-song-label').innerHTML=`${query?`Research “${esc(query)}”`:'Find another song with AI'}<small>Web research with source links</small>`}
function knob(k,v){return `<label class="knob-control"><span class="knob-label">${labels[k]}</span><span class="knob" id="knob-${k}" style="--value:${v}" aria-hidden="true"><span class="knob-indicator"></span></span><output id="output-${k}" for="range-${k}">${v.toFixed(1)}</output><input id="range-${k}" data-knob="${k}" aria-label="${labels[k]}" type="range" min="0" max="10" step="0.1" value="${v}"></label>`}
function sourceLinks(sources){return sources?.length?`<div class="source-list">${sources.map(s=>`<a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗${s.supports?`<small style="display:block;margin-top:7px;color:var(--muted);line-height:1.5">${esc(s.supports)}</small>`:''}</a>`).join('')}</div>`:'<p class="muted">No recording-specific sources are attached to this starting recipe.</p>'}
function renderSession(){const tone=selected;
  $('#session').innerHTML=`<div class="session-head"><div><div class="eyebrow">${esc(tone.section||'YOUR CUSTOM SOUND')} / ${tone.origin==='research'?'AI-ASSISTED RECIPE':'TONE RECIPE'}</div><h2>${esc(tone.title)}</h2><p class="artist">${esc(tone.artist||'Your own starting point')}</p></div><span class="status-badge">Estimated settings</span></div><div class="tone-field"><canvas id="tone-canvas" aria-hidden="true"></canvas><div class="field-caption"><span>${esc(tone.style||'Custom tone')}</span><span class="visual-note">Tone shape · illustrative</span></div></div><div class="rig-strip"><div><small>ADAPTED FOR YOUR RIG</small><strong>${esc(rig.guitar)} <span style="color:#829e8c">/</span> ${esc(rig.amp.name)}</strong></div><button data-view="rig">Edit rig</button></div><div class="settings-area"><div class="settings-heading"><div><div class="eyebrow">AMP / ${esc(result.channel)}</div><h3>A starting point. Then trust your ears.</h3></div><button class="text-button" data-action="reset-knobs">Reset</button></div><div class="knobs">${result.controls.map(k=>knob(k,values[k])).join('')}${knob('guitarTone',guitarTone)}</div><p class="scale-note">0–10 = approximate knob travel. “Gtr tone” is your guitar’s tone knob. Set amp volume separately.</p><div class="result-actions"><button class="button primary" data-action="save-tone">${icon('save')} Save this tone</button><button class="button secondary" data-action="copy-tone" aria-label="Copy tone settings">${icon('copy')}</button></div></div><div class="signal-section"><h3>Build the signal chain</h3><div class="signal-chain"><div class="signal-node"><strong>Guitar</strong><small>${esc(pickupNames[rig.pickup])}</small></div>${result.effects.filter(e=>['gate','compression','overdrive','distortion','fuzz'].includes(e.type)).map(signalNode).join('')}<span class="chain-arrow" aria-hidden="true">→</span><div class="signal-node"><strong>Amp</strong><small>${esc(tone.family)}</small></div>${result.effects.filter(e=>!['gate','compression','overdrive','distortion','fuzz'].includes(e.type)).map(signalNode).join('')}</div><details class="notes-panel"><summary>Pickup, effects & fine-tuning</summary><p><strong>Pickup:</strong> ${esc(tone.pickup)}</p><div class="effect-settings">${result.effects.map(e=>`<div class="effect-detail"><strong>${esc(e.name)} ${e.optional?'· optional':''}</strong><p>${esc(e.settings)}</p><p>${e.available?`Use: ${esc(e.device)}`:'This effect is not in your rig.'}</p></div>`).join('')}</div><p>${esc(tone.tip)}</p><ul>${result.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul><p>Signal order is conceptual. Use your amp’s effects loop for delay/modulation only when supported; otherwise place them after drive pedals before the amp.</p></details><details class="notes-panel"><summary>What is this based on?</summary><p>These are original estimated recipes and simple pickup-output adjustments, not a measured match or a verified studio rig. Source links below provide limited equipment context; they do not establish the knob values.</p><div style="margin-top:12px">${sourceLinks(tone.sources)}</div>${rig.amp.sources?.length?`<h3 style="margin:16px 0 10px;font-size:14px">Your amp’s controls</h3>${sourceLinks(rig.amp.sources)}`:''}</details></div>`;
  appendGrounding($('#session'),[{title:selected.title,data:selected.research},...gearResearch()]);animateTone();
}
function gearResearch(){return [{title:rig.guitar,data:rig.guitarResearch},{title:rig.amp.name,data:rig.amp.research},...rig.pedals.map(p=>({title:p.name,data:p.research}))]}
function searchAttribution(data){return data.searchProvider==='tavily'?'Sources found with Tavily':'Sources found with Google Search'}
function appendGrounding(parent,entries){for(const entry of entries.filter(e=>e.data?.rawText)){const section=document.createElement('section');section.className='grounding-section';section.innerHTML='<h3>AI research · '+esc(entry.title)+'</h3><p class="library-note">'+searchAttribution(entry.data)+'</p><details class="notes-panel"><summary>Original research & sources</summary><pre class="research-report">'+esc(entry.data.rawText)+'</pre>'+supportLinks(entry.data)+sourceLinks(entry.data.sources)+'</details>';if(entry.data.searchProvider!=='tavily'&&entry.data.searchEntryPoint){const frame=document.createElement('iframe');frame.className='search-entry';frame.title='Google Search suggestions for '+entry.title;frame.setAttribute('sandbox','allow-popups allow-popups-to-escape-sandbox');frame.srcdoc=entry.data.searchEntryPoint;section.append(frame)}parent.append(section)}}
function signalNode(e){return `<span class="chain-arrow" aria-hidden="true">→</span><div class="signal-node"><strong>${esc(e.type)}</strong><small>${e.available?'In your rig':e.optional?'Optional':'Add effect'}</small></div>`}
function animateTone(){cancelAnimationFrame(animationId);const canvas=$('#tone-canvas');if(!canvas)return;const ctx=canvas.getContext('2d');if(!ctx)return;let width=0,height=0,last=0;
  const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
  function draw(time){if(!canvas.isConnected)return;const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);if(width!==rect.width||height!==rect.height){width=rect.width;height=rect.height;canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}
    if(time-last>32||!motion||reduce){last=time;ctx.clearRect(0,0,width,height);frame+=.018;const phase=motion&&!reduce?frame:0;for(let line=0;line<26;line++){ctx.beginPath();for(let x=0;x<=width;x+=3){const u=x/width,env=Math.pow(Math.sin(u*Math.PI),1.6),gain=values.gain||3;const y=height*.48+Math.sin(u*15+phase+line*.075)*(17+gain*1.9)*env+Math.sin(u*7-phase+line*.2)*13*env+(line-13)*1.5*env; x===0?ctx.moveTo(x,y):ctx.lineTo(x,y)}ctx.lineWidth=line%5===0?1.15:.7;ctx.strokeStyle=`rgba(${150+line*3},${205+line},${114+line*3},${.11+line*.009})`;ctx.stroke()}}
    if(motion&&!reduce&&!document.hidden)animationId=requestAnimationFrame(draw);
  }draw(0);
}
document.addEventListener('visibilitychange',()=>{if(document.hidden)cancelAnimationFrame(animationId);else if(view==='explore')animateTone()});
function rigView(){return `<section class="intro fade-in"><div><div class="eyebrow"><span class="line"></span>THE SOUND STARTS WITH YOU</div><h1>Meet <em>your rig.</em></h1></div><p>Search any model with AI, or set up the controls yourself.</p></section><div class="page-grid"><section class="panel fade-in"><div class="eyebrow">01 / YOUR SETUP</div><form id="rig-form"><label class="field"><span>Guitar model</span><input name="guitar" maxlength="120" required value="${esc(rig.guitar)}" placeholder="Manufacturer and model"></label><label class="field"><span>Pickup you’ll use</span><select name="pickup">${Object.entries(pickupNames).map(([v,n])=>`<option value="${v}" ${rig.pickup===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field"><span>Amplifier</span><select name="amp" id="amp-select">${AMPS.map(a=>`<option value="${a.id}" ${a.id===rig.amp.id?'selected':''}>${esc(a.name)}</option>`).join('')}${!AMPS.some(a=>a.id===rig.amp.id)?`<option value="${esc(rig.amp.id)}" selected>${esc(rig.amp.name)}</option>`:''}</select></label><label class="field"><span>Amp name / custom model</span><input id="amp-name" name="ampName" maxlength="120" required value="${esc(rig.amp.name)}"></label><div class="field"><span>Available amp controls</span><div class="check-list" id="amp-control-list">${controlChecks(rig.amp.controls)}</div><small>Untick controls your amp does not have. All values are normalized starting estimates.</small></div><h3>Pedals & external effects</h3><div class="check-list">${EFFECT_TYPES.map(t=>`<label class="check-option"><input type="checkbox" name="pedal" value="${t}" ${rig.pedals.some(p=>p.type===t)?'checked':''}>${t}</label>`).join('')}</div>${rig.pedals.length?`<p class="demo-note" style="margin-top:13px">${rig.pedals.map(p=>esc(p.name)).join(' · ')}</p>`:''}<div class="inline-notice">Matching uses your selected pickup type, available amp controls and effects. Model specifications help identify the right controls; they do not reveal an instrument’s exact recorded tone.</div><button class="button primary" type="submit">Save rig ${icon('arrow')}</button></form>${rig.guitarSources?.length?`<details class="notes-panel"><summary>Guitar research sources</summary>${sourceLinks(rig.guitarSources)}</details>`:''}</section><section class="panel fade-in delay-1"><div class="eyebrow">02 / FIND YOUR GEAR</div><h2>Every rig has a story.</h2><p>Start with a known profile, or ask AI to look up the exact model and its specifications.</p><label class="field"><span>What are you looking for?</span><select id="gear-kind"><option value="guitar">Guitar</option><option value="amp">Amplifier</option><option value="pedal">Pedal / effect</option></select></label><label class="search-field">${icon('search')}<input id="gear-search" type="search" maxlength="160" placeholder="e.g. Yamaha Pacifica 612VII" aria-label="Search gear"></label><div class="catalog-results" id="catalog-results"></div><button class="research-cta" data-action="research-gear"><span class="spark">✧</span><span>Research this model with AI<small>Specs, tone characteristics & sources</small></span><span style="margin-left:auto">↗</span></button><p class="library-note">Include the model year or series when you can. You’ll review the research before adding it.</p></section></div>`}
function controlChecks(controls){return KNOB_KEYS.map(k=>`<label class="check-option"><input type="checkbox" name="ampControl" value="${k}" ${controls.includes(k)?'checked':''}>${labels[k]}</label>`).join('')}
function renderCatalog(){const term=$('#gear-search').value.toLowerCase(),kind=$('#gear-kind').value;const items=kind==='guitar'?GUITARS:kind==='amp'?AMPS: EFFECT_TYPES.map(t=>({name:t,type:t,description:'Generic effect type'}));const list=items.filter(a=>`${a.name} ${a.description||''}`.toLowerCase().includes(term));$('#catalog-results').innerHTML=list.length?list.map(a=>`<button class="catalog-item" data-catalog="${esc(kind)}" data-name="${esc(a.name)}"><span>${esc(a.name)}<small>${kind==='amp'?'Control profile · manual-linked':esc(a.description||'Generic profile')}</small></span>${icon('plus')}</button>`).join(''):`<p class="library-note">No built-in profile. Research the exact model below, or enter it manually.</p>`}
function savedView(){return `<section class="intro fade-in"><div><div class="eyebrow"><span class="line"></span>YOUR PERSONAL TONE BOOK</div><h1>Keep the <em>good ones.</em></h1></div><div class="toolbar"><button class="button secondary" data-action="import">Import</button><button class="button primary" data-action="export">${icon('download')} Export backup</button></div></section><p class="muted" style="font-size:14px;margin-bottom:24px">Saved on this device. Export a backup to take your tones to your phone, tablet or PC.</p>${saved.length?`<div class="saved-grid">${saved.map(s=>`<article class="saved-card fade-in"><div class="eyebrow">${esc(s.tone.style||'Custom tone')}</div><h2>${esc(s.tone.title)}</h2><p>${esc(s.tone.artist)}</p><div class="saved-eq">${KNOB_KEYS.filter(k=>s.rig.amp.controls.includes(k)).map(k=>`<span><small>${labels[k]}</small>${s.values[k].toFixed(1)}</span>`).join('')}</div><p>${esc(s.rig.guitar)} · ${esc(s.rig.amp.name)}</p><div class="actions" style="margin-top:18px"><button class="button primary" data-load="${esc(s.id)}">Load tone & rig ${icon('arrow')}</button><button class="icon-button" data-delete="${esc(s.id)}" aria-label="Remove ${esc(s.tone.title)}">${icon('trash')}</button></div></article>`).join('')}</div>`:`<section class="empty"><h2 style="margin-bottom:14px">Your next favorite is out there.</h2><p>Save a tone after dialing it in. Your settings and rig will be kept together.</p><button class="button primary" data-view="explore">Explore tones ${icon('arrow')}</button></section>`}`}
function openModal(title,content){modalEpoch++;researchAbort?.abort();if(widgetId!==null&&window.turnstile){window.turnstile.remove(widgetId);widgetId=null}researchToken='';lastFocus=document.activeElement;$('#modal-content').innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${content}</div>`;if(!modal.open)modal.showModal();}
function closeModal(){modal.close()}
modal.addEventListener('close',()=>{modalEpoch++;researchAbort?.abort();researchData=null;if(widgetId!==null&&window.turnstile){window.turnstile.remove(widgetId);widgetId=null}if(lastFocus?.isConnected)lastFocus.focus()});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
function settingsModal(){openModal('App settings',`<p>Your data stays in this browser. Research queries are sent to the configured AI service, search provider Tavily and Google only when you submit them.</p><form id="settings-form"><label class="field"><span>AI research service URL</span><input type="url" name="apiBase" placeholder="https://your-worker.workers.dev" value="${esc(apiBase)}"><small>Public service address only. Never paste an API key here. The site owner connects the service once for everyone.</small></label><label class="field"><span>Turnstile public site key</span><input name="siteKey" maxlength="150" value="${esc(siteKey)}" placeholder="Public site key"><small>Used to protect the free AI search quota.</small></label><label class="check-option"><input name="motion" type="checkbox" ${motion?'checked':''}>Animate the tone visualization</label><div class="modal-actions"><button class="button primary" type="submit">Save settings</button><button class="button secondary" type="button" data-action="export">Export backup</button></div></form><p class="version" style="margin-top:24px">ToneZero ${CONFIG.version} · ${storageOK?'Device storage available':'Storage unavailable'}</p>`)}
function aboutModal(){openModal('A little about ToneZero',`<p>ToneZero is an independent, free guitar tone workspace inspired by the idea of adapting a sound to the gear you own. It is not affiliated with ToneAdapt, Why Zero or any equipment manufacturer.</p><h3>How matching works</h3><p>Built-in recipes are original estimates for a specific song section. The app adjusts a few values for pickup output, shows only your available amp controls, and identifies missing effects. It does not analyze recordings or emulate amps, and it cannot guarantee a matching sound.</p><h3>AI research</h3><p>When connected, the service uses Tavily to find web sources and Google Gemini to interpret song context and gear specifications. Earlier research may use Google Search; each result identifies its search provider. Sources and uncertainty are shown before you use a result. Knob values remain estimates, even when the gear specifications are sourced. Review the exact model and year.</p><p>Research requires an internet connection. Free-tier quotas and availability apply. The app does not sell subscriptions or enable paid upgrades.</p><h3>Your data</h3><p>No analytics or account system. Your rig and tones stay in local browser storage. Export and import a backup to move them between devices. Clearing browser data removes local saves.</p><h3>Design references</h3><div class="source-list"><a href="https://www.toneadapt.com/" target="_blank" rel="noopener noreferrer">ToneAdapt — product reference ↗</a><a href="https://why.zero.university/" target="_blank" rel="noopener noreferrer">Why Zero — visual inspiration ↗</a><a href="https://ai.google.dev/gemini-api/docs/pricing" target="_blank" rel="noopener noreferrer">Gemini free-tier availability and data use ↗</a></div><p style="margin-top:16px">Original code and interface. No paid content, proprietary datasets, logos or artwork were copied.</p>`)}
async function installApp(){if(installPrompt){try{await installPrompt.prompt();const choice=await installPrompt.userChoice;if(choice.outcome==='accepted')toast('Installation started.');installPrompt=null}catch{installHelp()}}else installHelp()}
function installHelp(){openModal('Take your tone with you',`<p>Install from the hosted HTTPS website after it has loaded once.</p><h3>Samsung phone & tablet</h3><ol><li>Open this website in Chrome or Samsung Internet.</li><li>Open the browser menu and choose <strong>Install app</strong> or <strong>Add to Home screen</strong>.</li><li>Launch ToneZero from its new home-screen icon.</li></ol><h3>Windows PC</h3><p>Open the hosted site in Chrome or Edge. Use the install icon in the address bar or the browser’s Apps / Install menu.</p><div class="inline-notice">The app and saved tones work offline after the first successful load. AI research and source links need an internet connection. This is an installable web app, not an APK.</div><p>For another device, use Saved tones → Export backup, then Import on that device.</p>`)}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});window.addEventListener('appinstalled',()=>{installPrompt=null;toast('ToneZero is installed.')});
function showResearch(kind,term=''){researchKind=kind;lastResearchQuery=term;researchData=null;openModal(kind==='song'?'Find a song’s sound':'Research your gear',`<p>${kind==='song'?'Name the song, artist and section. AI will research the sound and suggest a starting recipe.':'Include the manufacturer, model and year. AI will search for specifications and explain what they mean for your sound.'}</p><form id="research-form"><label class="field"><span>${kind==='song'?'Song, artist & section':'Exact model'}</span><input name="query" id="research-query" maxlength="160" minlength="3" required value="${esc(term)}" placeholder="${kind==='song'?'e.g. Radiohead — Creep, chorus':'e.g. Yamaha Pacifica 612VII FM'}"></label><div id="turnstile-container"></div><button class="button primary" id="research-submit" type="submit">✧ Search with AI</button></form><div id="research-result" aria-live="polite"></div><p class="library-note">This query is sent to the app’s AI service, search provider Tavily and Google. Free-tier queries may be used to improve Google’s products. No microphone or files are sent.</p>`);if(apiBase&&siteKey)setupTurnstile(modalEpoch);}
async function setupTurnstile(epoch){try{if(!window.turnstile){await new Promise((resolve,reject)=>{let script=document.querySelector('script[data-turnstile]');if(script){script.addEventListener('load',resolve,{once:true});script.addEventListener('error',reject,{once:true});if(script.dataset.failed)reject(new Error('Verification could not load.'));return}script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.dataset.turnstile='1';script.onload=resolve;script.onerror=()=>{script.dataset.failed='1';reject(new Error('Verification could not load.'))};document.head.append(script)})}if(epoch!==modalEpoch||!modal.open||!$('#turnstile-container'))return;widgetId=window.turnstile.render('#turnstile-container',{sitekey:siteKey,action:'research',theme:'dark',callback:token=>{researchToken=token},'expired-callback':()=>{researchToken=''},'error-callback':()=>{researchToken='';$('#research-result').innerHTML='<div class="inline-notice warning">Verification is unavailable. Check your connection and try again.</div>'}})}catch{if(epoch===modalEpoch&&$('#research-result'))$('#research-result').innerHTML='<div class="inline-notice warning">Could not load search verification. Check your connection, then reopen this dialog.</div>'}}
async function doResearch(form){const target=$('#research-result'),term=cleanText(new FormData(form).get('query'),160);lastResearchQuery=term;
  if(!apiBase||!siteKey){target.innerHTML='<div class="inline-notice warning">AI research is not connected on this installation yet. The site owner needs to connect the research service and its public verification key. Built-in tones and manual rig setup are available now.</div><button class="button secondary" data-action="settings">Connect research service</button>';return}
  if(!navigator.onLine){target.innerHTML='<div class="inline-notice warning">You’re offline. Reconnect to research a model, or use a built-in profile.</div>';return}
  if(!researchToken){target.innerHTML='<div class="inline-notice warning">Complete the verification above, then search again.</div>';return}
  const epoch=modalEpoch;researchAbort=new AbortController();const timeout=setTimeout(()=>researchAbort?.abort(),65000);const button=$('#research-submit');button.disabled=true;target.innerHTML='<div class="research-status"><span class="spinner" aria-hidden="true"></span>Searching the web and checking sources…</div>';
  try{const response=await fetch(apiBase+'/api/research',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:researchKind,query:term,token:researchToken}),signal:researchAbort.signal,cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(cleanText(data.error,400)||'Research is unavailable right now.');const parsed=validateResearch(data,researchKind);if(!Array.isArray(data.sources)||!data.sources.some(s=>safeUrl(s.url)))throw new Error('No usable web sources were returned. Try a more specific model.');if(epoch!==modalEpoch)return;researchData={...parsed,...validateGrounding(data)};renderResearch();}
  catch(e){if(epoch===modalEpoch)target.innerHTML=`<div class="inline-notice warning">${esc(e.name==='AbortError'?'The search timed out. Please try again.':e.message)}</div>`}
  finally{clearTimeout(timeout);if(epoch===modalEpoch){button.disabled=false;researchToken='';if(widgetId!==null&&window.turnstile)window.turnstile.reset(widgetId)}}
}
function renderResearch(){const d=researchData,p=d.profile;$('#research-result').innerHTML=`<div class="research-mode"><span class="pill">AI research · review before using</span><h3>${esc(p.name||p.title)}</h3><p class="research-report">${esc(d.summary)}</p>${p.specs?.length?`<div class="spec-grid">${p.specs.map(s=>`<div><small>${esc(s.label)}</small>${esc(s.value)}</div>`).join('')}</div>`:''}${p.controls?`<p class="library-note">Supported controls: ${p.controls.map(k=>labels[k]).join(', ')}. Values will be approximate knob positions.</p>`:''}${d.caveats?`<div class="inline-notice warning">${esc(d.caveats)}</div>`:''}<h3>${searchAttribution(d)}</h3>${sourceLinks(d.sources)}<div id="search-suggestions"></div><details class="notes-panel"><summary>Original AI response</summary><pre class="research-report">${esc(d.rawText)}</pre>${supportLinks(d)}</details><div class="modal-actions"><button class="button primary" data-action="use-research">${researchKind==='song'?'Use this tone recipe':'Add to my rig'} ${icon('arrow')}</button></div><p class="library-note">Research can miss revisions and modifications. Check the specifications against your instrument before using them.</p></div>`;if(d.searchProvider!=='tavily'&&d.searchEntryPoint){const frame=document.createElement('iframe');frame.className='search-entry';frame.title='Google Search suggestions';frame.setAttribute('sandbox','allow-popups allow-popups-to-escape-sandbox');frame.srcdoc=d.searchEntryPoint;$('#search-suggestions').append(frame)}}
function useResearch(){if(!researchData)return;const d=researchData,p=d.profile,research=validateGrounding(d);if(researchKind==='song'){selected={...p,id:'ai-'+crypto.randomUUID(),sources:d.sources,research,origin:'research'};recalculate();closeModal();changeView('explore');toast('Research recipe loaded. Fine-tune before saving.')}else{if(researchKind==='guitar'){rig.guitar=p.name;rig.pickup=p.pickup;rig.guitarSources=d.sources;rig.guitarResearch=research}else if(researchKind==='amp')rig.amp={...p,id:'ai-amp-'+crypto.randomUUID(),sources:d.sources,research};else {if(rig.pedals.length>=16){toast('Your rig has 16 pedals. Remove one before adding another.');return}rig.pedals.push({name:p.name,type:p.type,research});}persist();recalculate();closeModal();changeView('rig');savedFeedback('Researched gear added to your rig.')}}
function customTone(){openModal('Create a starting tone',`<p>Name any song or your own sound, choose its character, then fine-tune the controls. This creates a manual recipe without AI research.</p><form id="custom-tone-form"><label class="field"><span>Song or tone name</span><input name="title" maxlength="100" required placeholder="My clean rhythm"></label><label class="field"><span>Artist (optional)</span><input name="artist" maxlength="100"></label><label class="field"><span>Starting character</span><select name="family"><option value="clean">Clean</option><option value="pushed">Edge of breakup</option><option value="crunch">Crunch</option><option value="lead">Lead</option><option value="high-gain">High gain</option></select></label><button class="button primary" type="submit">Create tone ${icon('arrow')}</button></form>`)}
function saveTone(){if(saved.length>=200){toast('Your library has 200 tones. Export a backup before removing older tones.');return}saved.unshift({id:crypto.randomUUID(),tone:structuredClone(selected),rig:structuredClone(rig),values:{...values},guitarTone,created:new Date().toISOString(),note:''});persist();savedFeedback(`Saved “${selected.title}” to this device.`)}
function toneText(){return `TONEZERO — ${selected.title}${selected.artist?' / '+selected.artist:''}\n${selected.section||''}\nEstimated starting settings, not verified recording settings.\n\nGuitar: ${rig.guitar} (${pickupNames[rig.pickup]})\nAmp: ${rig.amp.name}\nChannel: ${result.channel}\n${result.controls.map(k=>`${labels[k]}: ${values[k]}/10`).join('\n')}\nGuitar tone: ${guitarTone}/10\nPickup: ${result.pickup}\n\n${result.effects.map(e=>`${e.name}: ${e.settings} (${e.device})`).join('\n')}\n\n${selected.tip}\n${result.notes.join('\n')}\n\nSources:\n${[...(selected.sources||[]),...(rig.amp.sources||[])].map(s=>s.title+' — '+s.url).join('\n')}`}
async function copyTone(){try{await navigator.clipboard.writeText(toneText());toast('Settings copied.')}catch{openModal('Copy your settings',`<label class="field"><span>Select and copy this text</span><textarea readonly rows="13">${esc(toneText())}</textarea></label>`);$('textarea').select()}}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function exportBackup(){try{const parts=backupParts(rig,saved),stamp=new Date().toISOString().slice(0,10);if(parts.length===1){download('tonezero-backup-'+stamp+'.json',parts[0],'application/json');toast('Backup downloaded. Import it on your other device.')}else{openModal('Download your backup', '<p>Your library needs '+parts.length+' backup files. Download every part and import them one at a time on your other device.</p><div class="modal-actions">'+parts.map((_,i)=>'<button class="button secondary" data-backup-part="'+i+'">Download part '+(i+1)+'</button>').join('')+'</div>');document.querySelectorAll('[data-backup-part]').forEach(b=>b.onclick=()=>download('tonezero-backup-'+stamp+'-part-'+(Number(b.dataset.backupPart)+1)+'.json',parts[Number(b.dataset.backupPart)],'application/json'))}}catch(e){toast(e.message)}}
function importBackup(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files[0];if(!file)return;try{if(file.size>MAX_BACKUP_BYTES)throw new Error('This backup is too large (maximum 16 MB per part).');const data=validateBackup(JSON.parse(await file.text()));const ids=new Set(saved.map(s=>s.id));const incoming=data.saved.filter(s=>!ids.has(s.id));if(saved.length+incoming.length>200)throw new Error('The combined library would exceed 200 tones. Export and remove older tones first.');saved.push(...incoming.map(s=>({...s,id:s.id||crypto.randomUUID()})));persist();render();openModal(storageOK?'Backup imported':'Imported into memory only',`<p>${storageOK?'':'Export a backup before closing: device storage is unavailable. '}${incoming.length} tone${incoming.length===1?'':'s'} added. Your existing tones and current rig were kept.</p><p>This backup also contains: <strong>${esc(data.rig.guitar)} / ${esc(data.rig.amp.name)}</strong>.</p><div class="modal-actions"><button class="button primary" id="import-rig">Use imported rig</button><button class="button secondary" data-action="close-modal">Keep my current rig</button></div>`);$('#import-rig').onclick=()=>{rig=data.rig;recalculate();persist();closeModal();render();savedFeedback('Imported rig loaded.')}}catch(e){toast(e instanceof SyntaxError?'This file is not valid JSON.':e.message)}};input.click()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
  if(b.dataset.view){changeView(b.dataset.view);return}
  if(b.dataset.filter){filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(el=>{el.classList.toggle('active',el.dataset.filter===filter);el.setAttribute('aria-pressed',String(el.dataset.filter===filter))});renderList();return}
  if(b.dataset.tone){selected=TONES.find(t=>t.id===b.dataset.tone);recalculate();renderList();renderSession();if(innerWidth<=680)$('#session').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});return}
  if(b.dataset.catalog){const name=b.dataset.name;if(b.dataset.catalog==='guitar'){const g=GUITARS.find(g=>g.name===name);rig.guitar=g.name;rig.pickup=g.pickup;rig.guitarSources=[];rig.guitarResearch=null}else if(b.dataset.catalog==='amp')rig.amp=structuredClone(AMPS.find(a=>a.name===name));else if(!rig.pedals.some(p=>p.type===name))rig.pedals.push({name,type:name});persist();recalculate();render();savedFeedback('Profile added to your rig.');return}
  if(b.dataset.load){const s=saved.find(s=>s.id===b.dataset.load);selected=structuredClone(s.tone);rig=structuredClone(s.rig);recalculate();values={...s.values};guitarTone=s.guitarTone;persist();changeView('explore');savedFeedback('Saved tone and rig loaded.');return}
  if(b.dataset.delete){const item=saved.find(s=>s.id===b.dataset.delete);openModal('Remove saved tone?',`<p>Remove “${esc(item.tone.title)}” from this device? Export a backup first if you want to keep a copy.</p><div class="modal-actions"><button class="button danger" data-confirm-delete="${esc(item.id)}">Remove tone</button><button class="button secondary" data-action="close-modal">Keep it</button></div>`);return}
  if(b.dataset.confirmDelete){saved=saved.filter(s=>s.id!==b.dataset.confirmDelete);persist();closeModal();render();savedFeedback('Tone removed.');return}
  const action=b.dataset.action;
  if(action==='install')installApp();else if(action==='close-modal')closeModal();else if(action==='settings')settingsModal();else if(action==='about')aboutModal();else if(action==='research-song')showResearch('song',query);else if(action==='research-gear')showResearch($('#gear-kind').value,$('#gear-search').value);else if(action==='use-research')useResearch();else if(action==='custom-tone')customTone();else if(action==='save-tone')saveTone();else if(action==='copy-tone')copyTone();else if(action==='reset-knobs'){recalculate();renderSession();toast('Starting settings restored.')}else if(action==='export')exportBackup();else if(action==='import')importBackup();
});
document.addEventListener('input',e=>{if(e.target.id==='tone-search'){query=e.target.value;renderList()}if(e.target.id==='gear-search')renderCatalog();const k=e.target.dataset.knob;if(k){const v=clamp(e.target.value);if(k==='guitarTone')guitarTone=v;else values[k]=v;$('#output-'+k).textContent=v.toFixed(1);$('#knob-'+k).style.setProperty('--value',v);if(!motion||matchMedia('(prefers-reduced-motion: reduce)').matches)animateTone()}});
document.addEventListener('change',e=>{if(e.target.id==='gear-kind'){renderCatalog();$('#gear-search').placeholder=e.target.value==='amp'?'e.g. BOSS Katana-50 Gen 3':e.target.value==='pedal'?'e.g. BOSS DS-1':'e.g. Yamaha Pacifica 612VII'}if(e.target.id==='amp-select'){const a=AMPS.find(a=>a.id===e.target.value)||rig.amp;$('#amp-name').value=a.name;$('#amp-control-list').innerHTML=controlChecks(a.controls)}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,data=new FormData(form);
  if(form.id==='rig-form'){const amp=AMPS.find(a=>a.id===data.get('amp'))||rig.amp;const controls=data.getAll('ampControl');if(!controls.length){toast('Select at least one amp control.');return}const changedName=String(data.get('ampName')).trim()!==amp.name;rig=validateRig({guitar:data.get('guitar'),pickup:data.get('pickup'),amp:{...amp,name:data.get('ampName'),controls,...(changedName?{id:'custom-'+crypto.randomUUID(),channels:structuredClone(AMPS[0].channels),builtin:[],cleanNoGain:false,menuControls:[],sources:[],research:null,notes:'Custom amp: channel names are generic suggestions. Built-in effects have not been assumed. Use AI research to identify this model’s capabilities.'}:{})},pedals:data.getAll('pedal').map(type=>rig.pedals.find(p=>p.type===type)||{name:type,type}),guitarSources:rig.guitar===String(data.get('guitar')).trim()?rig.guitarSources:[],guitarResearch:rig.guitar===String(data.get('guitar')).trim()?rig.guitarResearch:null});persist();recalculate();changeView('explore');savedFeedback('Rig saved. Your tone has been adapted.');}
  if(form.id==='settings-form'){const raw=String(data.get('apiBase')).trim(),endpoint=validEndpoint(raw);if(raw&&!endpoint){toast('Enter a valid HTTPS service URL.');return}apiBase=endpoint;siteKey=cleanText(data.get('siteKey'),150);motion=data.has('motion');persist();closeModal();render();savedFeedback('App settings saved.');}
  if(form.id==='research-form')doResearch(form);
  if(form.id==='custom-tone-form'){const family=data.get('family'),gain={clean:2,pushed:3.5,crunch:5,lead:6,'high-gain':7}[family];selected={id:'custom-'+crypto.randomUUID(),title:cleanText(data.get('title'),100),artist:cleanText(data.get('artist'),100),section:'Custom recipe',style:family,family,base:{gain,bass:5,middle:5,treble:5,presence:5},pickup:'Use the pickup that best fits the sound you want.',effects:[],tip:'Play the same short phrase while changing one control at a time.',sources:[],origin:'custom'};recalculate();closeModal();changeView('explore');}
});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!modal.open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();if(view!=='explore')changeView('explore');$('#tone-search').focus()}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['explore','rig','saved'].includes(next)){view=next;render()}});
function connectionState(){$('#connection-state').textContent=navigator.onLine?'Free to play. Yours to keep.':'Offline · your local tones are ready.'}window.addEventListener('online',connectionState);window.addEventListener('offline',connectionState);
if('serviceWorker' in navigator){window.addEventListener('load',()=>{navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{toast('Offline setup could not finish. Reload while online to try again.')})})}
recalculate();render();connectionState();if(restoreNotice)toast(restoreNotice);

// Optional browser-agent tools. Normal browsers work without this proposed API.
const modelContext=document.modelContext;
if(modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'list_tone_recipes',title:'List tone recipes',description:'Read the built-in recipe catalog and current selected tone. Does not search the internet or modify the rig.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:160}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='query')||(input.query!==undefined&&typeof input.query!=='string'))throw new Error('Expected an optional query string.');return {selected:selected.id,tones:TONES.filter(t=>(t.title+' '+t.artist).toLowerCase().includes((input.query||'').toLowerCase())).map(t=>({id:t.id,title:t.title,artist:t.artist,style:t.style}))}}},{name:'load_tone_recipe',title:'Load a tone recipe',description:'Load one built-in tone into the visible workspace with estimated settings adapted to the current rig. Does not save a preset or change the rig.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.id!=='string'||Object.keys(input).some(k=>k!=='id'))throw new Error('Expected a tone ID.');const found=TONES.find(t=>t.id===input.id);if(!found)throw new Error('Unknown tone ID.');selected=found;recalculate();changeView('explore');return {loaded:selected.id,estimated:true,channel:result.channel,values:{...values},controls:result.controls}}}];for(const tool of tools){try{Promise.resolve(modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{/* unsupported preview implementation */}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

function supportLinks(data){return (data.supports||[]).length?'<div class="evidence-links"><h3>'+(data.searchProvider==='tavily'?'Source excerpts':'Source-linked evidence')+'</h3>'+data.supports.map(s=>'<p>'+esc(s.text)+' '+s.sourceIndices.filter(i=>data.sources[i]).map(i=>'<a href="'+esc(safeUrl(data.sources[i].url))+'" target="_blank" rel="noopener noreferrer">['+(i+1)+']</a>').join(' ')+'</p>').join('')+'</div>':''}
